          for c in range(c0,c1):
            if grid[r][c] in marks: marks[grid[r][c]].append((ri,ci))
    lines={2:set(),3:set()}
    for color,points in marks.items():
      # Each aligned pair draws a finite segment between its marker cells.
      for i,(r1,c1) in enumerate(points):
        for r2,c2 in points[i+1:]:
          if r1==r2:
            for c in range(min(c1,c2),max(c1,c2)+1): lines[color].add((r1,c))
          elif c1==c2:
            for r in range(min(r1,r2),max(r1,r2)+1): lines[color].add((r,c1))
    out=[row[:] for row in grid]
    for ri,(r0,r1) in enumerate(rows):
      for ci,(c0,c1) in enumerate(cols):
        if r1-r0!=mh or c1-c0!=mw: continue
        has2=(ri,ci) in lines[2]; has3=(ri,ci) in lines[3]
        color=6 if has2 and has3 else 2 if has2 else 3 if has3 else 0
        for r in range(r0,r1):
          for c in range(c0,c1): out[r][c]=color
    return out
